#!/usr/bin/env node
// Content remains in LanceDB; local files are generated by content-pull.
import { listCollection, upsertEntry } from '../src/lib/content-store.ts';
import { validateCollectionFields } from '../src/lib/content-schemas.ts';
import { fetchProjectReadme } from '../src/lib/project-readme.ts';

const args = process.argv.slice(2);
const slugIndex = args.indexOf('--slug');
const slug = slugIndex >= 0 ? args[slugIndex + 1] : undefined;
const all = args.includes('--all');
const dryRun = args.includes('--dry-run');
if ((!all && !slug) || (all && slug) || (slugIndex >= 0 && (!slug || slug.startsWith('--')))) {
  throw new Error('Usage: node scripts/sync-project-readmes.mjs (--all | --slug <slug>) [--dry-run]');
}

const records = (await listCollection('projects')).filter(record => all || record.path === slug);
if (!records.length) throw new Error('No matching projects found');
for (const record of records) {
  try {
    const fields = JSON.parse(record.frontmatter);
    const readmeSnapshot = await fetchProjectReadme(fields.repoUrl);
    const validated = validateCollectionFields('projects', { ...fields, readmeSnapshot });
    if (!validated.ok) throw new Error(validated.error);
    if (!dryRun) await upsertEntry({ ...record, frontmatter: JSON.stringify(validated.frontmatter), updatedAt: new Date().toISOString() });
    console.log(`${dryRun ? 'PREVIEW' : 'SAVED'} ${record.path}: ${readmeSnapshot.summary} (${readmeSnapshot.sections.length} sections, ${readmeSnapshot.images.length} images)`);
  } catch (error) {
    console.error(`${record.path}: ${error.message}`);
    process.exitCode = 1;
  }
}
